<script setup lang="ts">
defineOptions({name:'AipptDesign'})
import { ref,computed,onMounted,onBeforeUnmount,watch } from 'vue'
import {checkPermi} from '@/utils/permission'
import { api,download } from '@/api/aippt'
import { ensureCatalog } from '@/composables/aippt/useCatalog'
import { waitTask } from '@/composables/aippt/useTaskResult'
import {resolveQualityReport} from '@/composables/aippt/qualityReport'
import { themeList,layouts,getTheme,catalogVersion } from '../render/design'
import type { Deck,Issue,Task } from '@/types/aippt'
import SlideStage from '../editor/SlideStage.vue'
import PresentOverlay from '../editor/PresentOverlay.vue'
const deck=ref<Deck|null>(null),themeId=ref('ivory'),index=ref(0),error=ref(''),loading=ref(false),issues=ref<Issue[]>([]),present=ref(false),exported=ref<Task|null>(null),ready=ref(false),qualityBusy=ref(false),exportBusy=ref(false),qualityReady=ref(false),allowed=ref(false),acknowledged=ref(false);let controller=new AbortController(),generation=0,command:{key:string;body:Record<string,unknown>}|null=null
const theme=computed(()=>ready.value?getTheme(themeId.value):null),current=computed(()=>deck.value?.slides[index.value])
const warnings=computed(()=>issues.value.some(i=>i.severity==='warning'))
async function load(){loading.value=true;try{await ensureCatalog();deck.value=await api.sample();themeId.value=deck.value.theme_id||'ivory';ready.value=true;error.value=''}catch(e:any){error.value=e.message}finally{loading.value=false}}
async function check(){controller.abort();controller=new AbortController();const local=controller,own=++generation,selected=themeId.value;qualityBusy.value=true;qualityReady.value=false;allowed.value=false;issues.value=[];acknowledged.value=false;exported.value=null;error.value='';command=null;try{const report=await resolveQualityReport(()=>api.sampleIssues(selected),local.signal);if(own!==generation||selected!==themeId.value)return;issues.value=report.issues||[];allowed.value=(report.can_export??report.export_allowed)===true;qualityReady.value=true}catch(e:any){if(own===generation&&e.name!=='AbortError'&&e.code!=='ERR_CANCELED')error.value=e.message}finally{if(own===generation){qualityBusy.value=false;exportBusy.value=false}}}
async function exportSample(){if(!qualityReady.value||!allowed.value||warnings.value&&!acknowledged.value||qualityBusy.value||exportBusy.value)return;controller.abort();controller=new AbortController();const local=controller,own=++generation,selected=themeId.value;exportBusy.value=true;error.value='';try{const body={theme_id:selected,acknowledge_warnings:acknowledged.value};if(!command||JSON.stringify(command.body)!==JSON.stringify(body))command={key:crypto.randomUUID(),body};const task=await api.sampleExport(command.body,command.key);if(own!==generation)return;exported.value=task;await waitTask(task,local.signal);if(own!==generation||selected!==themeId.value||local.signal.aborted)return;if(!task.id)throw new Error('样例导出缺少文件标识');const result=await api.exportState('',task.id);if(own!==generation||selected!==themeId.value)return;if(!['ready','completed'].includes(result.status))throw new Error('样例导出回读未通过');exported.value=result;await download(result.download_url||`/exports/${task.id}/download`,'设计样例-'+selected+'.pptx');command=null}catch(e:any){if(own===generation&&e.name!=='AbortError'&&e.code!=='ERR_CANCELED')error.value=e.message}finally{if(own===generation)exportBusy.value=false}}
watch(()=>[ready.value,themeId.value],()=>{if(ready.value)void check()});onMounted(load);onBeforeUnmount(()=>{generation++;controller.abort()})
</script>
<template><div class="app-container design" v-loading="loading"><header><div><h2>样例与主题</h2><p>这是目录样例，用于了解版式与原生内容，未计入本人生成项目。目录版本：{{catalogVersion}}</p></div><el-button :disabled="!deck" @click="present=true">放映样例</el-button><el-button v-hasPermi="['aippt:export:create']" :disabled="!deck||!qualityReady||qualityBusy||exportBusy||!allowed||warnings&&!acknowledged||!checkPermi(['aippt:export:download'])" type="primary" @click="exportSample">导出样例 PPTX</el-button></header><el-alert v-if="error" type="error" :title="error"><el-button @click="load">重试</el-button></el-alert><div v-if="theme&&deck" class="design-workspace"><aside><h3>四套主题</h3><el-button v-for="t in themeList" :key="t.id" :type="themeId===t.id?'primary':'default'" @click="themeId=t.id">{{t.name}}</el-button><h3>11种固定版式</h3><div v-for="l in layouts.values()" :key="l.id" class="layout"><strong>{{l.name}}</strong><small>{{l.id}} · {{l.slots.length}}个槽位</small><span>{{[...new Set(l.slots.flatMap(s=>s.accepts))].join(' / ')}}</span></div></aside><main><div class="sample-controls"><el-button :disabled="index===0" @click="index--">上一页</el-button><el-select v-model="index" aria-label="选择样例页"><el-option v-for="(slide,i) in deck.slides" :key="slide.id" :label="(i+1)+'. '+(slide.title||slide.layout_id)" :value="i"/></el-select><el-button :disabled="index===deck.slides.length-1" @click="index++">下一页</el-button></div><SlideStage v-if="current" :slide="current" :theme="theme" :index="index"/><h3>样例质量提示</h3><p v-if="qualityBusy" aria-live="polite">正在检查所选主题样例…</p><el-checkbox v-if="warnings" v-model="acknowledged">已了解样例警告，按所选主题导出</el-checkbox><el-button :loading="qualityBusy" @click="check">重新检查样例</el-button><el-alert v-for="(issue,i) in issues" :key="i" :title="issue.message" :type="issue.severity==='error'?'error':'warning'" :closable="false"/><el-alert v-if="qualityReady&&!allowed" title="所选主题样例暂不允许导出，请处理质量提示后重新检查。" type="warning" :closable="false"/><el-empty v-if="qualityReady&&allowed&&!issues.length" description="当前样例未发现质量问题"/></main></div><PresentOverlay v-if="present&&deck&&theme" :slides="deck.slides" :theme="theme" :start="index" @close="i=>{index=i;present=false}"/></div></template>
<style scoped>header{display:flex;align-items:center;gap:14px;flex-wrap:wrap}header>div{margin-right:auto}header p{color:#606266;line-height:1.5}.design-workspace{display:grid;grid-template-columns:250px minmax(280px,1fr);gap:24px;margin-top:24px}aside .el-button{margin:4px}.layout{padding:12px 0;border-bottom:1px solid #ebeef5}.layout small,.layout span{display:block;margin-top:6px;color:#909399;font-size:12px}.sample-controls{display:flex;align-items:center;gap:14px;margin-bottom:16px}.sample-controls .el-select{flex:1}.el-alert{margin-top:12px}@media(max-width:960px){.design-workspace{grid-template-columns:1fr}.layout{display:inline-block;width:50%;vertical-align:top}}</style>


